#define ANKERL_NANOBENCH_IMPLEMENT
#include <nanobench.h>

#include "bench_csv.h"

#include "ctrlpp/model/state_space.h"
#include "ctrlpp/sysid/moesp.h"
#include "ctrlpp/sysid/batch_arx.h"

#include <Eigen/Dense>

#include <fstream>

namespace
{

constexpr int record_length = 200;
constexpr int markov_count = 40;
constexpr double a1 = 1.5;
constexpr double a2 = -0.7;
constexpr double b1 = 0.5;
constexpr double b2 = 0.2;

using identified_system = ctrlpp::discrete_state_space<double, 2, 1, 1>;

// The record is generated by an exactly second-order noise-free difference
// equation, so its Markov parameters are known in closed form and an identified
// model of that same order has nothing but its own arithmetic and conditioning
// standing between it and them. They are invariant under a change of state
// basis, which is what makes them comparable across two realizations.
Eigen::VectorXd generating_markov_parameters()
{
    Eigen::VectorXd g = Eigen::VectorXd::Zero(markov_count);
    g(1) = b1;
    g(2) = b2 + a1 * b1;
    for(int k = 3; k < markov_count; ++k)
        g(k) = a1 * g(k - 1) + a2 * g(k - 2);
    return g;
}

Eigen::VectorXd markov_parameters(const identified_system& sys)
{
    Eigen::VectorXd g(markov_count);
    Eigen::Matrix<double, 2, 1> state = sys.B;
    g(0) = sys.D(0, 0);
    for(int k = 1; k < markov_count; ++k)
    {
        g(k) = (sys.C * state)(0, 0);
        state = sys.A * state;
    }
    return g;
}

double markov_deviation(const identified_system& sys)
{
    const Eigen::VectorXd truth = generating_markov_parameters();
    return (markov_parameters(sys) - truth).cwiseAbs().maxCoeff() / truth.cwiseAbs().maxCoeff();
}

}

int main(int argc, char** argv)
{
    Eigen::RowVectorXd Y(record_length);
    Eigen::RowVectorXd U(record_length);
    Y.setZero();
    U.setZero();

    for(int k = 5; k < record_length; ++k)
        U(k) = 1.0;

    for(int k = 2; k < record_length; ++k)
        Y(k) = a1 * Y(k - 1) + a2 * Y(k - 2) + b1 * U(k - 1) + b2 * U(k - 2);

    auto arx = ctrlpp::batch_arx<2, 2>(Y, U);
    auto subspace = ctrlpp::moesp<2>(Y, U);
    if(!arx)
        return 1;

    ankerl::nanobench::Bench bench;
    bench.title("SysID")
        .warmup(10)
        .minEpochIterations(100)
        .performanceCounters(true);
    ctrlpp::bench::apply_smoke_switch(bench, argc, argv);

    ctrlpp::bench::run_single_implementation_row(bench, "batch_arx::identify", [&] {
        auto result = ctrlpp::batch_arx<2, 2>(Y, U);
        ankerl::nanobench::doNotOptimizeAway(result.has_value());
        ankerl::nanobench::doNotOptimizeAway(result);
    });

    ctrlpp::bench::run_single_implementation_row(bench, "moesp::identify", [&] {
        auto result = ctrlpp::moesp<2>(Y, U);
        ankerl::nanobench::doNotOptimizeAway(result);
    });

    ctrlpp::bench::run_own_criterion_pair(
        bench, "max relative deviation of this model's Markov parameters from the generating system's",
        "batch_arx::identify", markov_deviation(arx->system),
        [&] {
            auto result = ctrlpp::batch_arx<2, 2>(Y, U);
            ankerl::nanobench::doNotOptimizeAway(result.has_value());
            ankerl::nanobench::doNotOptimizeAway(result);
        },
        "moesp::identify", markov_deviation(subspace.system),
        [&] {
            auto result = ctrlpp::moesp<2>(Y, U);
            ankerl::nanobench::doNotOptimizeAway(result);
        });

    std::ofstream csv("bench_sysid.csv");
    bench.render(ctrlpp::bench::csv_tpl, csv);
}
